local failureReasons, reportResult, failureMap, failureFlag, _packResults, _unpackResults, environment = ...

local function fail(message)
	reportResult(false, "gethiddenproperty", message)
	if failureMap.gethiddenproperty then
		failureFlag[1] = true
	end
end

-- Base64 of the expected AeroMeshData SharedString of workspace.seeba (11928 bytes).
local EXPECTED_AERO_MESH_DATA =
	""

return function()
	if not environment.getrawmetatable or failureReasons.getrawmetatable then
		fail("Can't test due to getrawmetatable not working properly")
		return
	end
	if not environment.setreadonly or failureReasons.setreadonly then
		fail("Can't test due to setreadonly not working properly")
		return
	end

	local part = environment.Instance.new("Part")
	local sizeSuccess, size = environment.pcall(environment.gethiddenproperty, part, "size_xml")
	if sizeSuccess == true and size ~= nil then
		fail("This is so FIRE \240\159\148\165\240\159\148\165\240\159\148\165")
	end

	local humanoid = environment.game.Players.LocalPlayer.Character.Humanoid
	humanoid.Health = 99
	local healthSuccess, health = environment.pcall(environment.gethiddenproperty, humanoid, "Health_XML")
	if not healthSuccess or health ~= 99 then
		fail("Couldn't retrieve the expected changed property")
	end

	local taggedPart = environment.Instance.new("Part")
	taggedPart:AddTag("Nigerian prince 0/0")
	if environment.gethiddenproperty(taggedPart, "Tags") ~= "Nigerian prince 0/0" then
		fail("Failed to get a binary string hidden property value")
	end
	-- Removes the tag from the Humanoid (not from taggedPart), as the original test does.
	environment.game.Players.LocalPlayer.Character.Humanoid:RemoveTag("Nigerian prince 0/0")

	local seeba = environment.workspace.seeba
	if #environment.gethiddenproperty(seeba, "AeroMeshData") == 0 then
		fail("SharedString result was empty[2]")
	end
	if #environment.gethiddenproperty(seeba, "AeroMeshData") ~= 11928 then
		fail("SharedString result length did not match with expected.")
	end
	if environment.base64encode(environment.gethiddenproperty(seeba, "AeroMeshData")) ~= EXPECTED_AERO_MESH_DATA then
		fail("Couldn't match returned SharedString with expected[2]")
	end

	-- gethiddenproperty on a signal (game.Close) whose __type is temporarily spoofed as "Instance";
	-- the result is ignored.
	environment.pcall(function()
		local close = environment.game.Close
		local metatable = environment.getrawmetatable(close)
		environment.setreadonly(metatable, false)
		local originalType = metatable.__type
		metatable.__type = "Instance"
		environment.pcall(environment.gethiddenproperty, close, "Tags")
		metatable.__type = originalType
		environment.setreadonly(metatable, true)
	end)
end
